-- Homebase: apply with `supabase db push` after linking a project.
create extension if not exists pgcrypto;
create schema if not exists private;
create type public.household_role as enum ('admin','adult','child');
create type public.occurrence_status as enum ('open','complete');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table public.households (id uuid primary key default gen_random_uuid(), name text not null check(char_length(name) between 1 and 100), created_by uuid not null default auth.uid() references auth.users(id), created_at timestamptz not null default now());
create table public.memberships (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.household_role not null default 'child', joined_at timestamptz not null default now(), unique(household_id,user_id));
create table public.join_codes (household_id uuid primary key references public.households(id) on delete cascade, code_hash text not null, rotated_at timestamptz not null default now(), rotated_by uuid not null references auth.users(id));
create table public.invite_links (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, token_hash text not null unique, role public.household_role not null default 'adult', expires_at timestamptz not null, used_at timestamptz, used_by uuid references auth.users(id), revoked_at timestamptz, created_by uuid not null default auth.uid() references auth.users(id), created_at timestamptz not null default now());
create table public.chores (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, title text not null, assignee_id uuid references auth.users(id), recurrence jsonb, next_due_at timestamptz not null, created_by uuid not null default auth.uid() references auth.users(id), created_at timestamptz not null default now());
create table public.chore_occurrences (id uuid primary key default gen_random_uuid(), chore_id uuid not null references public.chores(id) on delete cascade, household_id uuid not null references public.households(id) on delete cascade, title text not null, assignee_id uuid references auth.users(id), due_at timestamptz not null, status public.occurrence_status not null default 'open', completed_at timestamptz, unique(chore_id,due_at));
create table public.chore_completions (id uuid primary key default gen_random_uuid(), occurrence_id uuid not null unique references public.chore_occurrences(id) on delete cascade, completed_by uuid not null default auth.uid() references auth.users(id), completed_at timestamptz not null default now());
create table public.shopping_items (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, title text not null, quantity text, added_by uuid not null default auth.uid() references auth.users(id), checked_at timestamptz, checked_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.events (id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households(id) on delete cascade, title text not null, starts_at timestamptz not null, ends_at timestamptz not null check(ends_at>starts_at), created_by uuid not null default auth.uid() references auth.users(id), created_at timestamptz not null default now());
create table public.event_attendees (event_id uuid not null references public.events(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, primary key(event_id,user_id));
create table public.device_push_tokens (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, token text not null unique, platform text not null check(platform in ('ios','android')), last_seen_at timestamptz not null default now());
create table public.notification_deliveries (id uuid primary key default gen_random_uuid(), occurrence_id uuid references public.chore_occurrences(id) on delete cascade, event_id uuid references public.events(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, kind text not null check(kind in ('due_chore','overdue_chore','upcoming_event')), delivered_on date not null default current_date, created_at timestamptz not null default now(), unique(occurrence_id,user_id,kind,delivered_on), unique(event_id,user_id,kind,delivered_on));

create or replace function private.member_role(h uuid) returns public.household_role language sql stable security definer set search_path=public as $$select role from memberships where household_id=h and user_id=auth.uid()$$;
create or replace function private.is_member(h uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from memberships where household_id=h and user_id=auth.uid())$$;
create or replace function private.is_adult(h uuid) returns boolean language sql stable security definer set search_path=public as $$select private.member_role(h) in ('admin','adult')$$;
create or replace function private.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id) values(new.id) on conflict do nothing; return new; end$$;
create trigger create_profile after insert on auth.users for each row execute function private.new_profile();
create or replace function private.new_household_admin() returns trigger language plpgsql security definer set search_path=public as $$begin insert into memberships(household_id,user_id,role) values(new.id,new.created_by,'admin'); return new; end$$;
create trigger create_household_admin after insert on public.households for each row execute function private.new_household_admin();
create or replace function private.first_occurrence() returns trigger language plpgsql security definer set search_path=public as $$begin insert into chore_occurrences(chore_id,household_id,title,assignee_id,due_at) values(new.id,new.household_id,new.title,new.assignee_id,new.next_due_at); return new; end$$;
create trigger materialize_first_occurrence after insert on public.chores for each row execute function private.first_occurrence();
create or replace function private.finish_occurrence() returns trigger language plpgsql security definer set search_path=public as $$declare o public.chore_occurrences; c public.chores; next_due timestamptz; begin select * into o from chore_occurrences where id=new.occurrence_id for update; update chore_occurrences set status='complete',completed_at=new.completed_at where id=o.id; select * into c from chores where id=o.chore_id; if c.recurrence ? 'intervalDays' then next_due:=o.due_at+make_interval(days=>(c.recurrence->>'intervalDays')::int); elsif c.recurrence ? 'weekdays' then next_due:=o.due_at+interval '1 day'; while not ((c.recurrence->'weekdays') ? (extract(dow from next_due)::int)::text) loop next_due:=next_due+interval '1 day'; end loop; end if; if next_due is not null then insert into chore_occurrences(chore_id,household_id,title,assignee_id,due_at) values(c.id,c.household_id,c.title,c.assignee_id,next_due) on conflict do nothing; update chores set next_due_at=next_due where id=c.id; end if; return new; end$$;
create trigger apply_chore_completion after insert on public.chore_completions for each row execute function private.finish_occurrence();

alter table public.profiles enable row level security; alter table public.households enable row level security; alter table public.memberships enable row level security; alter table public.join_codes enable row level security; alter table public.invite_links enable row level security; alter table public.chores enable row level security; alter table public.chore_occurrences enable row level security; alter table public.chore_completions enable row level security; alter table public.shopping_items enable row level security; alter table public.events enable row level security; alter table public.event_attendees enable row level security; alter table public.device_push_tokens enable row level security; alter table public.notification_deliveries enable row level security;
create policy "profiles household" on public.profiles for select using(id=auth.uid() or exists(select 1 from memberships a join memberships b on a.household_id=b.household_id where a.user_id=auth.uid() and b.user_id=profiles.id)); create policy "own profile" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy "members read homes" on public.households for select using(private.is_member(id)); create policy "create own home" on public.households for insert with check(created_by=auth.uid()); create policy "admins update home" on public.households for update using(private.member_role(id)='admin');
create policy "members read memberships" on public.memberships for select using(private.is_member(household_id)); create policy "admins manage memberships" on public.memberships for all using(private.member_role(household_id)='admin') with check(private.member_role(household_id)='admin');
create policy "admins manage codes" on public.join_codes for all using(private.member_role(household_id)='admin') with check(private.member_role(household_id)='admin'); create policy "admins manage invites" on public.invite_links for all using(private.member_role(household_id)='admin') with check(private.member_role(household_id)='admin');
create policy "members read chores" on public.chores for select using(private.is_member(household_id)); create policy "adults manage chores" on public.chores for all using(private.is_adult(household_id)) with check(private.is_adult(household_id)); create policy "members read occurrences" on public.chore_occurrences for select using(private.is_member(household_id));
create policy "assignee completes" on public.chore_completions for insert with check(exists(select 1 from chore_occurrences o where o.id=occurrence_id and (o.assignee_id=auth.uid() or private.is_adult(o.household_id)))); create policy "members read completions" on public.chore_completions for select using(exists(select 1 from chore_occurrences o where o.id=occurrence_id and private.is_member(o.household_id)));
create policy "members read shopping" on public.shopping_items for select using(private.is_member(household_id)); create policy "members add shopping" on public.shopping_items for insert with check(private.is_member(household_id) and added_by=auth.uid()); create policy "members update shopping" on public.shopping_items for update using(private.is_member(household_id)) with check(private.is_member(household_id)); create policy "adults delete shopping" on public.shopping_items for delete using(private.is_adult(household_id));
create policy "members read events" on public.events for select using(private.is_member(household_id)); create policy "members create events" on public.events for insert with check(private.is_member(household_id) and created_by=auth.uid()); create policy "author or adult updates event" on public.events for update using(private.is_adult(household_id) or created_by=auth.uid()) with check(private.is_adult(household_id) or created_by=auth.uid()); create policy "author or adult deletes event" on public.events for delete using(private.is_adult(household_id) or created_by=auth.uid());
create policy "members read attendees" on public.event_attendees for select using(exists(select 1 from events e where e.id=event_id and private.is_member(e.household_id))); create policy "event owner manages attendees" on public.event_attendees for all using(exists(select 1 from events e where e.id=event_id and (private.is_adult(e.household_id) or e.created_by=auth.uid()))) with check(exists(select 1 from events e where e.id=event_id and (private.is_adult(e.household_id) or e.created_by=auth.uid())));
create policy "own push tokens" on public.device_push_tokens for all using(user_id=auth.uid()) with check(user_id=auth.uid());
